Under Assumptions 1 1. to 4., there exists $\delta^0, t_0, r_0>0$ and $C>0$ such that for every $\delta \in (0,\delta^0)$, $t\in [0,t_0)$, $r_\bullet \geq r_0$, $r\geq 2r_\bullet$ and every $r_\bullet \leq R \leq  r-r_\bullet$, 
\begin{multline}
w_t(r) = \mathbb{E}^{(t)}\Bigg[ I^{(r,R,\delta)} w_t(r-Z) \exp\Big( \ln\mathbb{E}^{(t)}[\chi(\mathbb{R})] - w_t(r-Z) - \frac{1}{2} \int w_t(r-y) \mathrm{d} M^{(r,R,\delta)}_{Z} (y) \\
+ \mathbb{E}^{(t)}\left[ I^{(r,R,\delta)} w_t(r-Z) \right] \Big) \Bigg] + \mathrm{Remainder}_t(r,R,\delta) ,
\end{multline}
where 
\begin{equation*} 
C_\mathrm{rem} |\mathrm{Remainder}_t(r,R,\delta)| \leq \mathbb{P}(\Lambda>R) + \mathbb{P}\left(\chi(\mathbb{R})>\frac{\delta}{w_t(r-R)}\right) + (\sigma^2 + 1) w_t(r-R)^2 \left( w_t(r-R) + \delta \right) .
\end{equation*}

Under Assumptions 1 1. to 4., there exists $\delta^0>0$ and $r_0>0$ such that for every $\delta \in (0,\delta^0)$, $r_\bullet \geq r_0$, $r\geq 2r_\bullet$ and for every $r_\bullet \leq R \leq  r-r_\bullet$, 
\begin{multline}
w(r) = \mathbb{E}\Bigg[ I^{(r,R,\delta)} w(r-Z) \exp\Big( - w(r-Z) - \frac{1}{2} \int w(r-y) \mathrm{d} M^{(r,R,\delta)}_{Z} (y) \\
+ \mathbb{E}\left[ I^{(r,R,\delta)} w(r-Z) \right] \Big) \Bigg] + \mathrm{Remainder}(r,R,\delta) ,
\end{multline}
where
\begin{equation*} 
\frac{1}{90}|\mathrm{Remainder}(r,R,\delta)| \leq \mathbb{P}(\Lambda>R) + \mathbb{P}\left(\chi(\mathbb{R})>\frac{\delta}{w(r-R)}\right) + (\sigma^2 + 1) w(r-R)^2 \left( w(r-R) + \delta \right) .
\end{equation*}

For every $\alpha>0$, $0<C_-<1<C_+<\infty$ and $a\in (0,a_\alpha)$, recalling $a_\alpha$, $r_\alpha$ and $T_a$ from Lemma 28, 
there exist two functions $\underline{\delta}(y)\underset{y \to \infty}{\longrightarrow} 0$ with values in $(0,\delta^0)$ and $g(y) \underset{y \to \infty}{\longrightarrow} 0$ such that 
for every $A>0$, $r\geq 2r_\alpha$, $x \in [C_- r, C_+ r]$ and every $t\in[0,t(r,\alpha)] $, letting $\delta_n = \underline{\delta}(r)$ for every $n$, $R_n = \mathcal{R} := a/\sqrt{w_t(C_- r)}$ for every $n$, and $S_0 = r$ a.s., 
writing $\tau_x = \inf\{ n\geq 0 : S_n \leq x \}$ and $T' = \inf(\tau_x, A/w(x), T_a)$, 
\begin{equation}
\left| w_t(r) - \mathbb{E}^{(t)}\left[ W^{(r)}_{T'}\right] \right| \leq A w_t(x) g(x) . 
\end{equation}

There exists a function $\underline{\delta} : [0,\infty) \to (0,\delta^0)$ decreasing with $\underline{\delta}(y) \to 0$ as $y\to\infty$ and a function $g:(0,1] \to [0,\infty)$ increasing with $g(x)\to 0$ as $x\to 0$ such that the following holds. 

For every $a\in (0,a_0)$, $A>0$, $y>0$, $\mathcal{R}>0$, and $r \geq x \geq r_0$ where $a_0, r_0$ is given by Lemma 15, setting $\delta_n = \underline{\delta}(y)$ for every $n$ and writing 
\begin{equation*}
\begin{cases}
\tau_x = \inf\{ n\geq 0 : S_n \leq x \} \\
\rho = \inf\{n\geq 0 : S_n-R_n < y \text{ or } R_n < \mathcal{R}\} \\
T' = \inf(\tau_x, T_a, \rho, A/w(x) \}
\end{cases}
\end{equation*}
then 
\begin{equation}
\left| w(r) - \mathbb{E}\left[ W^{(r)}_{T'}\right] \right| \leq  \frac{100 A}{w(x)} \left( \mathbb{P}(\Lambda > \mathcal{R}) + w(y)^2 g(w(y))\right) .
\end{equation}

Any limit $\phi_\alpha$ in (94) satisfies
\begin{equation}
\phi_\alpha(y) = \mathbb{E}^{y/\eta}\left[\exp\left( -\frac{\sigma^2}{2} \int_0^{\tau_0} \phi_\alpha(\eta B_s) \mathrm{d} s - \frac{\alpha \mathcal{L}(0)}{\mathcal{L}(\alpha)} \tau_0 \right)\right] . 
\end{equation}

Any limit $\phi$ in (36) satisfies
\begin{equation}
\phi(y) = \mathbb{E}^{y/\eta}\left[ \exp\left(-\frac{\sigma^2}{2} \int_0^{\tau_0^B} \phi\left(\eta B_u\right) \mathrm{d} u \right) \right] \quad \text{ for every } y\geq 0 .
\end{equation}

The random variables $(Z_t)_{t\geq 0}$ from (71) satisfy (70), and in addition
\begin{equation}
\limsup_{t\to 0} \ (2\sigma^2 t)^{-1/2} \mathbb{P}(Z_t \neq Z) \leq 1 .
\end{equation}
and
\begin{equation}
\mathbb{E}[(Z_t - Z_0)^2] \underset{t \to 0}{\longrightarrow} 0 .
\end{equation}

For every $\alpha\geq 0$, 
define 
\[ D(\alpha) = \frac{4}{\eta\sqrt{\pi}} \sqrt{\sigma^2 + \frac{\alpha}{c(\alpha)}} \ . \]
For every $y\geq 0$
\begin{equation}
\liminf_{r\to\infty} \frac{w_{t(r, \alpha)}\left(r + \frac{y}{\sqrt{w_{t(r, \alpha)}(r)}}\right)}{w_{t(r, \alpha)}(r)} \geq 1 - y D(\alpha) .
\end{equation}

There exists a neighborhood $I$ of $0$ and two non-increasing continuous functions $F_-, F_+$ on $I$ with $F_-(0) = F_+(0) = 1$ such that for every $y\in I$, 
\begin{align}
F_-\left( \frac{\sigma}{\eta} y \right) 
&\leq \liminf_{r\to\infty} \frac{w\left( r + \frac{y}{\sqrt{w(r)}}\right)}{w(r)} \\
&\leq \limsup_{r\to\infty} \frac{w\left( r + \frac{y}{\sqrt{w(r)}}\right)}{w(r)} \leq F_+\left( \frac{\sigma}{\eta} y \right) . 
\end{align}
We can take 
\begin{equation*}
F_-(y) = \begin{cases} 
1-y\sqrt{\frac{8}{\pi}} \geq 1-2y &\text{if } y\geq 0 \\
1 						&\text{if } y<0 
\end{cases} \qquad , \qquad 
F_+(y) = \begin{cases}
1 &\text{if } y\geq 0 \\
f^{-1}(-y) &\text{if }y<0 \text{ large enough}
\end{cases}
\end{equation*}
where $f: [1,3] \to [0, \frac{\sqrt{\pi}}{3\sqrt{6}}] , x\mapsto \frac{1-x^{-1}}{\sqrt{x}}\sqrt{\pi/8}$.

\begin{align}
F_-\left( \frac{\sigma}{\eta} y \right) 
&\leq \liminf_{r\to\infty} \frac{w\left( r + \frac{y}{\sqrt{w(r)}}\right)}{w(r)} \\
&\leq \limsup_{r\to\infty} \frac{w\left( r + \frac{y}{\sqrt{w(r)}}\right)}{w(r)} \leq F_+\left( \frac{\sigma}{\eta} y \right) . 
\end{align}

For every $\alpha>0$ and $y\geq 0$, recalling $D(\alpha)$ from Lemma 25, 
\begin{equation}
\liminf_{r\to\infty} \inf_{0\leq t \leq t(r,\alpha)} \frac{w_t\left(r + \frac{y}{\sqrt{w_t(r)}}\right)}{w_t(r)} \geq
\begin{cases}
1 - y D(\alpha)  &\text{ if } y\geq 0, \\
1 &\text{ if } y\leq 0 ,
\end{cases}
\end{equation}
and for every $y > - \frac{2}{\mathrm{e} D(\alpha)}$, 
\begin{equation}
\limsup_{r\to\infty} \sup_{0\leq t \leq t(r,\alpha)} \frac{w_t\left(r + \frac{y}{\sqrt{w_t(r)}}\right)}{w_t(r)} \leq 
\begin{cases}
f_\alpha^{-1}(-y)  &\text{ if } y\leq 0 , \\
1 &\text{ if } y\geq 0 ,
\end{cases}
\end{equation}
where $f_\alpha^{-1}$ is the inverse of the function $f_\alpha : [1,3] \to [0, \frac{2}{D(\alpha) 3\sqrt{3}} ] , x \mapsto \frac{1-x^{-1}}{D(\alpha)\sqrt{x}} $.

There exists a neighborhood $I$ of $0$ and two non-increasing continuous functions $F_-, F_+$ on $I$ with $F_-(0) = F_+(0) = 1$ such that for every $y\in I$, 
